// Initialize OpenVDB global registries. This is thread-safe and idempotent.
// Track init calls in global fuzzer state to model idempotence and enable
// follow-up validation by other stubs.
int prev = FUZZ_GET_ATTR_INT_GLOBAL("openvdb_initialized");

// Invoke the target function. Safe to call multiple times; we call once here
// to keep the harness focused and rely on the global counter for sequencing.
openvdb::OPENVDB_VERSION_NAME::initialize();

// Record that initialize was called. We use a reference count style counter
// to allow uninitialize() to decrement back toward zero without asserting.
FUZZ_SET_ATTR_INT_GLOBAL("openvdb_initialized", prev + 1);

// No outputs; global initialization is process-wide state.

// Unregister OpenVDB factories. Thread-safe and may be called multiple times.
// Does not tear down blosc; we do not attempt to manage blosc here.
int prev = FUZZ_GET_ATTR_INT_GLOBAL("openvdb_initialized");

// Invoke the target function. API allows calling even if not previously
// initialized; treat as a no-op in that case.
openvdb::OPENVDB_VERSION_NAME::uninitialize();

// Decrement our tracked count, saturating at zero to reflect idempotent API.
int next = (prev > 0) ? (prev - 1) : 0;
FUZZ_SET_ATTR_INT_GLOBAL("openvdb_initialized", next);

// No outputs; global state only.
